{
  "items": [
    {
      "fact_text": {
        "text": "In Java, string objects are reference types and cannot be compared with the == or != operators because these operators compare object addresses, not their values.",
        "refs": ["Q0000", "Q0001", "Q0002", "Q0003"],
        "claims": [
          {
            "text": "String objects are reference types and cannot be compared with == or != operators.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0000", "Q0001", "Q0002", "Q0003"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "To compare the value of two strings in Java you must use the equals method (e.g., input.equals(\"quit\")).",
        "refs": ["Q0004", "Q0005"],
        "claims": [
          {
            "text": "String values must be compared using the equals method.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0004", "Q0005"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "To loop until the user types \"quit\", the condition should be written as !input.equals(\"quit\") so the loop continues while the input is not equal to \"quit\".",
        "refs": ["Q0006"],
        "claims": [
          {
            "text": "Use !input.equals(\"quit\") as the loop condition to continue while input is not \"quit\".",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0006"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "A Scanner object should be created once outside the loop; creating a new Scanner inside each iteration creates unnecessary objects and pollutes memory.",
        "refs": ["Q0007", "Q0008", "Q0009", "Q0010", "Q0011"],
        "claims": [
          {
            "text": "Create the Scanner object outside the loop to avoid creating many Scanner instances.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0007", "Q0008", "Q0009", "Q0010", "Q0011"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "If user input may contain uppercase letters, convert the input to lower case before comparing to \"quit\".",
        "refs": ["Q0013", "Q0014"],
        "claims": [
          {
            "text": "Convert input to lower case before comparison to handle case variations.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0013", "Q0014"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "A while loop checks its condition before each iteration; if the condition is false the first time, the loop body never executes.",
        "refs": ["Q0031", "Q0032"],
        "claims": [
          {
            "text": "While loops evaluate the condition before each iteration; a false initial condition prevents any execution.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0031", "Q0032"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "A do‑while loop executes its body at least once because the condition is evaluated after the body.",
        "refs": ["Q0033", "Q0034", "Q0035"],
        "claims": [
          {
            "text": "Do‑while loops always run the body once before checking the condition.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0033", "Q0034", "Q0035"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "In practice, while loops are used more frequently than do‑while loops; do‑while loops are reserved for cases where the body must run at least once.",
        "refs": ["Q0036", "Q0037"],
        "claims": [
          {
            "text": "While loops are preferred in most code; do‑while loops are used when at least one execution is required.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0036", "Q0037"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "When the program echoes user input, the word \"quit\" is also echoed before the program terminates, which may be undesirable.",
        "refs": ["Q0041"],
        "claims": [
          {
            "text": "Echoing input causes \"quit\" to be printed before termination.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "identified_mistake",
            "refs": ["Q0041"],
            "related_refs": []
          }
        ]
      },
      "fact_type": null
    }
  ],
